"""Spend accounting that survives the process, because the process is not the unit.

A per-run bound is only a bound if the run happens once. Under a scheduler, a
supervisor, or a self-relaunching driver, N runs of a bounded allocation is an
unbounded bill, and each fresh process honestly reports itself as compliant.
So the allocation has to be held somewhere that outlives any single run and be
charged before the next one is admitted.
"""

from __future__ import annotations

import json
import os
import tempfile
import time
from dataclasses import dataclass, field

STATE = os.environ.get("AGENT_SPEND_STATE", "var/spend.json")
WINDOW_SECONDS = 7 * 24 * 3600
WEEKLY_CAP_USD = 40.0


@dataclass
class SpendLedger:
    entries: list[dict] = field(default_factory=list)

    @classmethod
    def load(cls) -> "SpendLedger":
        try:
            with open(STATE, encoding="utf-8") as fh:
                return cls(entries=json.load(fh))
        except FileNotFoundError:
            return cls()

    def spend_to_date(self) -> float:
        floor = time.time() - WINDOW_SECONDS
        return sum(e["usd"] for e in self.entries if e["at"] >= floor)

    def remaining_for_next_run(self, requested_usd: float) -> float:
        left = WEEKLY_CAP_USD - self.spend_to_date()
        return min(requested_usd, max(left, 0.0))

    def explain_refusal(self) -> str:
        return (
            f"refusing to start: {self.spend_to_date():.2f} USD already spent in the "
            f"current window against a cap of {WEEKLY_CAP_USD:.2f} USD"
        )

    def record(self, usd: float) -> None:
        self.entries.append({"at": time.time(), "usd": usd})
        os.makedirs(os.path.dirname(STATE) or ".", exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=os.path.dirname(STATE) or ".")
        with os.fdopen(fd, "w", encoding="utf-8") as fh:
            json.dump(self.entries, fh)
        os.replace(tmp, STATE)
